/* runs one step of a moby's timed state and reports whether the timer ran out */
int process_linked_switch_damage(Moby *m, char *arg, float *t) {
    struct HitMessage *r = (struct HitMessage *)MobyGetHitMessage(m, 0x330000, 0);
    int n;
    int result = 0;
    char *e;
    switch (ComputeHitResponse(m, r, t, 0, &n, 0, 0, 4)) {
        case 0:
            break;
        case 1:
            *(int *)t = 0;
            break;
        case 2:
            *(int *)t = 0;
            break;
        case 3:
        case 4:
        case 5:
        case 6:
        case 7:
        case 8:
        case 9:
        case 10:
        case 11:
            break;
    }
    e = arg + 0x60;
    if (n >= 2) {
        float lim = r->damage;
        unsigned short fl;
        if (*t <= lim) {
            *(int *)t = 0;
            fl = m->flags;
            m->flags = fl & 0xEFFF;
            *(unsigned char *)(arg + 0x67) = 0x78;
            RerollEffectCounter(m, (short *)e);
            result = 1;
        } else {
            *t = *t - lim;
            *(unsigned char *)(arg + 0x67) = 0xFA;
            *(short *)(arg + 0x26) = scale_ticks(0x3C);
            RerollEffectCounter(m, (short *)e);
        }
    }
    m->hit_slot = 0xFF;
    StepColorFade(m, e);
    return result;
}
