/* Adapted from Lombyte's project (GPL-3.0) for PAL by OpenRAC's tools/port.py: src/overlays/l13/gameplay/entities/002c13b0.c, FUN_L13_002e9408. */
int update_moby_path_following_away_from_hero(struct Moby *m, char *d, int idx, int aim) {
    char *path = walker_paths[*(int *)(&d[idx << 2] + 0xB0)];
    int r = 0;
    float ahead[4];
    float behind[4];
    float a, b;
    int n;
    int k;
    int dir;
    if (path != 0) {
        n = *(short *)(d + 0x9C) + 1;
        if (n >= *(int *)path) {
            n = 0;
        }
        qcopy(ahead, path + n * 16 + 0x10);
        a = fast_vec_dist(ahead, hero_pos);
        k = *(short *)(d + 0x9C) - 1;
        if (k < 0) {
            k = *(int *)path - 1;
        }
        qcopy(behind, path + k * 16 + 0x10);
        b = fast_vec_dist(behind, hero_pos);
        if (a < b) {
            dir = -1;
        } else if (b < a) {
            dir = 1;
        } else {
            dir = d[0x10C] == 1 ? 1 : -1;
        }
        if (dir != (signed char)d[0x10C]) {
            float k = frame_scale;
            *(float *)(d + 0xAC) *= k * -0.100000024f + 1.0f;
            if (*(float *)(d + 0xAC) < k * 0.15f) {
                short cur = *(short *)(d + 0x9C);
                d[0x10C] = dir;
                *(short *)(d + 0x9C) = *(unsigned short *)(d + 0x9E);
                *(short *)(d + 0x9E) = cur;
            }
        } else {
            float dist = fast_vec_dist(&m->pos, hero_pos);
            float s = 1.0f;
            float sp;
            if (m->command == 4) {
                s = 3.0f;
            }
            sp = *(float *)(d + 0xAC);
            sp += (s * 30.0f / dist - sp) * (frame_scale * 0.12f);
            *(float *)(d + 0xAC) = sp;
            if (sp < 0.0f) {
                *(float *)(d + 0xAC) = 0.0f;
            }
        }
        r = advance_moby_along_selected_path(m, d, idx, aim);
    }
    if (0.0f < *(float *)(path + (*(short *)(d + 0x9C) << 4) + 0x1C)) {
        r |= 2;
    }
    return r;
}

/* Launches the child moby held in slot idx of p: spins it off with random-ish velocities and clears the slot. */
void detach_moby_joint_attachment(void *unused, char *p, int idx) {
    char *base = p + 0xC4;
    int off = idx * 4;
    char **slot = (char **)(base + off);
    Moby *moby = (Moby *)(*slot);
    if (moby != 0) {
        struct DetachedPartVars *data = (struct DetachedPartVars *)moby->pvars;
        float *v = &data->vel.x;
        float t, r0, r1, r2;
        cart_burst(unused, &moby->pos, -1, 2.0f, 13.0f);
        FastVecScale(v, p + 0x70, 0.95f);
        add_random_offset_to_vector_xyz(v, g_frame_time * 30.0f);
        moby->state = 3;
        FastVecAdd(&moby->pos, &moby->pos, v);
        t = g_frame_time;
        t = t * 0.34906585f;
        r0 = random_float_between(-t, t);
        t = g_frame_time;
        data->spin_x = r0;
        t = t * 3.1415927f;
        r1 = random_float_between(-t, t);
        t = g_frame_time;
        data->spin_y = r1;
        t = t * 3.1415927f;
        r2 = random_float_between(-t, t);
        data->spin_z = r2;
        *(long *)&moby->spawn_frame = 0x40404000000000L;
        moby->hit_slot = 0xFF;
        *slot = 0;
    }
}
