/* Per-frame update of a breakable vehicle part (level 13): probes the first attached object and then the
   eleven attached children for hits, takes damage from them, advances the damage stage (unkBC) with its
   effects and sounds, and runs the stage's follow-up action. */
void process_moby_attachment_damage(Moby *m, Data_2EAE80 *d) {
    int hit;
    int rf;
    int mode;
    int i;
    int k;
    int j;
    float lo;
    float hi;
    float k6;
    float step;
    Hit_2EAE80 *r;
    Sub *dd;

    if (m->state < 6) {
        dd = &d->sub;
        mode = 0;
        rf = 0;
        k6 = 6.0f;
        step = (float)dd->h4 / k6;
        hi = (k6 - IntToFloat(m->command)) * step;
        if (m->command >= 5) {
            hi = (k6 - IntToFloat(m->command - 1)) * step;
        }
        lo = hi + step * 0.3f;
        if (d->first != 0) {
            r = MobyGetHitMessage_r3(d->first, 0x230000, 0);
            ComputeHitResponse(m, r, dd, 0, &hit, 0, 0, 4);
            if (r != 0 && r->target != 0 &&
                (r->target->oclass == MOBY_CLASS_ORANGE_RADAR_CONTACT ||
                 r->target->oclass == MOBY_CLASS_YELLOW_RADAR_CONTACT ||
                 r->target->oclass == MOBY_CLASS_ASTEROID_212)) {
                d->first->hit_slot = 0xFF;
            } else if (hit >= 2) {
                if (0.0f < r->f2C && r->h2A == 0x3F1) {
                    r->f2C = 0.3f;
                }
                if (r != 0 && m->command == 7) {
                    r->f2C = r->f2C * 1.5f;
                }
                if (dd->f0 <= r->f2C) {
                    begin_starfighter_death_sequence_r(m, d, dd, r);
                    mode = 3;
                    d->first->hit_slot = 0xFF;
                } else {
                    dd->f0 = dd->f0 - r->f2C;
                    d->b67 = 0xFA;
                    mode = 1;
                    d->sub.h6 = scale_ticks(0);
                    RerollEffectCounter(m, d->q60);
                    d->first->hit_slot = 0xFF;
                }
                if (m->state == 7) {
                    m->command++;
                    rf = 1;
                    {
                        Vars *v = (Vars *)(*(Moby **)&g_hero.ship_moby)->pvars;

                        v->f88 = 0;
                        v->fEC = 0;
                        v->f8C = 0;
                        v->f118 = 0;
                    }
                } else if (dd->f0 < hi) {
                    int tv = l13_starfighter_attachment_slot_indices_by_command[m->command - 1];

                    if (tv != -1) {
                        Moby_PlaySound_r4(7, 0, m);
                        detach_moby_joint_attachment_r(m, d, tv);
                    }
                    if (m->state == 5) {
                        m->state = 4;
                    }
                    m->command++;
                    if (d->i11C != -1) {
                        if (((Voice *)(voice_pool + d->i11C * 0x70))->f88 == m &&
                            ((Voice *)(voice_pool + d->i11C * 0x70))->b74 != 0) {
                            Sound_StopSlot(d->i11C);
                        }
                        d->i11C = -1;
                    }
                    rf = 1;
                    {
                        Vars *v = (Vars *)(*(Moby **)&g_hero.ship_moby)->pvars;

                        v->f88 = 0;
                        v->fEC = 0;
                        v->f8C = 0;
                        v->f118 = 0;
                    }
                    d->h138 = 0;
                    d->b148 = 0;
                    mode = 2;
                    if (m->command == 7) {
                        for (j = m->command - 1; j < 10; j++) {
                            detach_moby_joint_attachment_r(m, d, l13_starfighter_attachment_slot_indices_by_command[j]);
                        }
                        Moby_PlaySound_r4(7, 0, m);
                    }
                } else if (dd->f0 < lo) {
                    d->b148 = 1;
                }
            }
        }
        for (i = 0; i < 11 && mode == 0; i++) {
            if (d->list[i] == 0) {
                continue;
            }
            r = MobyGetHitMessage_r3(d->list[i], 0x230000, 0);
            ComputeHitResponse(m, r, dd, 0, &hit, 0, 0, 4);
            if (r != 0 && r->target != 0 &&
                (r->target->oclass == MOBY_CLASS_ORANGE_RADAR_CONTACT ||
                 r->target->oclass == MOBY_CLASS_YELLOW_RADAR_CONTACT ||
                 r->target->oclass == MOBY_CLASS_ASTEROID_212)) {
                d->list[i]->hit_slot = 0xFF;
                continue;
            }
            if (hit < 2) {
                continue;
            }
            if (0.0f < r->f2C) {
                switch (r->h2A) {
                    case 0x3F1:
                        r->f2C = 0.1f;
                        break;
                    case 0x127:
                        r->f2C = r->f2C * 0.5f;
                        break;
                }
            }
            if (r != 0 && m->command == 7) {
                r->f2C = r->f2C * 1.5f;
            }
            if (dd->f0 <= r->f2C) {
                begin_starfighter_death_sequence_r(m, d, dd, r);
                mode = 3;
                d->list[i]->hit_slot = 0xFF;
            } else {
                dd->f0 = dd->f0 - r->f2C;
                d->b67 = 0xFA;
                mode = 1;
                d->sub.h6 = scale_ticks(0);
                RerollEffectCounter(m, d->q60);
                d->list[i]->hit_slot = 0xFF;
            }
            if (m->state == 7) {
                m->command++;
                rf = 1;
                {
                    Vars *v = (Vars *)((Hero *)g_hero_r)->ship_moby->pvars;

                    v->f88 = 0;
                    v->fEC = 0;
                    v->f8C = 0;
                    v->f118 = 0;
                }
            } else if (dd->f0 < hi) {
                int tv = l13_starfighter_attachment_slot_indices_by_command[m->command - 1];

                if (tv != -1) {
                    detach_moby_joint_attachment_r(m, d, tv);
                }
                Moby_PlaySound_r4(7, 0, m);
                if (m->state == 5) {
                    m->state = 4;
                }
                m->command++;
                if (d->i11C != -1) {
                    if (((Voice *)(voice_pool + d->i11C * 0x70))->f88 == m &&
                        ((Voice *)(voice_pool + d->i11C * 0x70))->b74 != 0) {
                        Sound_StopSlot(d->i11C);
                    }
                    d->i11C = -1;
                }
                rf = 1;
                {
                    Vars *v = (Vars *)((Hero *)g_hero_r)->ship_moby->pvars;

                    v->f88 = 0;
                    v->fEC = 0;
                    v->f8C = 0;
                    v->f118 = 0;
                }
                d->h138 = 0;
                d->b148 = 0;
                mode = 2;
                if (m->command == 7) {
                    for (k = m->command - 1; k < 10; k++) {
                        detach_moby_joint_attachment_r(m, d, l13_starfighter_attachment_slot_indices_by_command[k]);
                    }
                    Moby_PlaySound_r4(7, 0, m);
                }
            } else if (dd->f0 < lo) {
                d->b148 = 1;
            }
        }
        if (mode > 0) {
            if (rf != 0) {
                switch (m->command - 1) {
                    case 0:
                        break;
                    case 1:
                        queue_starfighter_voice_line_r(m, d, 0xC, 4);
                        break;
                    case 2:
                        d->f100 = scale_ticks(0x78);
                        queue_starfighter_voice_line_r(m, d, 0x10, 1);
                        break;
                    case 3:
                        queue_starfighter_voice_line_r(m, d, 0x11, 1);
                        break;
                    case 4:
                        break;
                    case 5:
                        queue_starfighter_voice_line_r(m, d, 0x13, 1);
                        break;
                    case 6:
                        queue_starfighter_voice_line_r(m, d, 0x16, 1);
                        break;
                    case 7:
                        break;
                }
            } else if (m->command == 7 && d->b148 != 0) {
                if (!(d->h138 & 1) && queue_starfighter_voice_line_r(m, d, 0x14, 2) != 0) {
                    d->h138 |= 1;
                }
                if (!(d->h138 & 2) && queue_starfighter_voice_line_r(m, d, 0x14, 2) != 0) {
                    d->h138 |= 2;
                }
            }
        }
    }
    StepColorFade(m, d->q60);
}

/* Steers a moby toward the hero: scales by distance and orients it with the hero's angles. */
void predict_hero_ship_projectile_lead_position(char *a, char *b, float f) {
    struct Hero *base = &g_hero;
    char *d = *(char **)(*(char **)&base->ship_moby + 0x78);
    float y = FastAddRots(*(float *)(*(char **)&base->ship_moby + 0x48), *(float *)(d + 0x90));
    float x = FastAddRots(*(float *)(*(char **)&base->ship_moby + 0x44), *(float *)(d + 0x94));
    float dist = fast_vec_dist(b, *(char **)&base->ship_moby + 0x10);
    float k = *(float *)(d + 0x64);
    BuildSphericalOffset(a, dist / (k + f) * k, y, -x);
    FastVecAdd(a, a, *(char **)&base->ship_moby + 0x10);
}

extern void predict_hero_ship_projectile_lead_position(char *a, char *b, float f);

/* Angles from pos to the hero's target (led by lead when positive) or to the hero; returns the yaw. */
float calculate_hero_aim_angles(float *pos, float *pitch, float *yaw, float lead) {
    struct Hero *base = &g_hero;
    char *t = *(char **)&base->ship_moby;
    float v[4];
    float y;
    float p;
    if (t != 0 && *(short *)(t + 0xA6) == 0x45) {
        if (lead > 0.0f) {
            predict_hero_ship_projectile_lead_position((char *)v, (char *)pos, lead);
        } else {
            qcopy(v, t + 0x10);
        }
        y = fast_atan2(v[0] - pos[0], v[1] - pos[1]);
        p = -fast_atan2(vec_distance_xy(pos, v), v[2] - pos[2]);
    } else {
        struct Hero *p0 = &g_hero;
        y = fast_atan2(p0->motion.pos.f[0] - pos[0], p0->motion.pos.f[1] - pos[1]);
        p = -fast_atan2(vec_distance_xy(pos, &p0->motion.pos), p0->motion.pos.f[2] - pos[2]);
    }
    if (yaw != 0)
        *yaw = y;
    if (pitch != 0)
        *pitch = p;
    return y;
}

extern void Moby_GetJointWorldPos_r3(char *, int, float *) __asm__("func_L00_00250800");
extern unsigned char *spawn_level_13_homing_rocket_r(char *, char *, char *, char *, float, int,
                                                     float) __asm__("func_L13_002C2638");
extern void calculate_hero_aim_angles_r(float *, float *, float *, float) __asm__("func_L13_002EB838");

extern void Moby_PlaySound_r5(int, int, char *) __asm__("func_0022ED80");

/* Adapted from Lombyte's project (GPL-3.0) for PAL by OpenRAC's tools/port.py: src/overlays/l13/gameplay/entities/002c13b0.c, FUN_L13_002ea540. */
unsigned char *fire_starfighter_homing_rocket(struct Moby *firing_moby, unsigned char *starfighter_data) {
    float muzzle_position[4];
    struct {
        int a;
        float b;
        float c;
    } s;
    int muzzle_joint_index;
    float projectile_speed;
    unsigned char *spawned_rocket_moby;
    struct Hero *hero_state;
    muzzle_joint_index = (starfighter_data[0xFC] & 1) ? 0x12 : 0x10;
    if (firing_moby->command != 6 || (func_001160D8() & 1)) {
        starfighter_data[0xFC] ^= 1;
    }
    Moby_GetJointWorldPos_r3(firing_moby, muzzle_joint_index, muzzle_position);
    s.a = 0;
    if (firing_moby->state != 5) {
        calculate_hero_aim_angles_r(muzzle_position, &s.b, &s.c, g_frame_time_r * 17.0f);
    } else {
        calculate_hero_aim_angles_r(muzzle_position, &s.b, &s.c, -1.0f);
    }
    hero_state = (struct Hero *)g_hero_r;
    projectile_speed = g_frame_time_r * 18.0f + *(float *)(starfighter_data + 0xAC);
    s.c = firing_moby->rot.z;
    s.b = 0.43633232f;
    spawned_rocket_moby =
        spawn_level_13_homing_rocket_r(firing_moby, (char *)muzzle_position, (char *)hero_state->ship_moby, (char *)&s,
                                       projectile_speed, scale_ticks(300), g_frame_time_r * 18.0f);
    if (spawned_rocket_moby != 0) {
        Moby_PlaySound_r5(2, 0, firing_moby);
    }
    return spawned_rocket_moby;
}

extern unsigned char *spawn_mine_83_projectile(char *owner, char *pos, char *vec);

/* computes a velocity vector for a moby from the camera/player and spawns a projectile */
unsigned char *fire_mine_83_projectile(char *a, char *b) {
    float v0[4], v1[4], v2[4], v3[4], v4[4];
    struct Hero *x;
    unsigned char *r;
    moby_point_position(a, 0xE, v0);
    x = &g_hero;
    if (*(char **)&x->ship_moby != 0 && *(short *)(*(char **)&x->ship_moby + 0xA6) == 0x45) {
        predict_hero_ship_projectile_lead_position((char *)v2, (char *)v0, g_frame_time * 20.0f);
        FastVecSub(v3, v2, v0);
        vec_scale_to_length(v1, v3, g_frame_time * 20.0f);
        vec_scale_to_length(v4, *(char **)&x->ship_moby + 0xD0,
                            random_float_between(-(g_frame_time * 30.0f), g_frame_time * 30.0f));
        vec_scale_to_length(v3, *(char **)&x->ship_moby + 0xE0,
                            random_float_between(-(g_frame_time * 30.0f), g_frame_time * 30.0f));
        FastVecAdd(v4, v4, v3);
        vec_scale_to_length(v4, v4, random_float_between(g_frame_time * 5.0f, g_frame_time * 30.0f));
        FastVecAdd(v1, v1, v4);
    } else {
        random_vector(v1, g_frame_time * 0.0f, g_frame_time * 30.0f);
    }
    FastVecAdd(v1, v1, b + 0x70);
    r = spawn_mine_83_projectile(a, (char *)v0, (char *)v1);
    if (r)
        Moby_PlaySound(3, 0, (int)a);
    return r;
}
